function retrieve(chunks, query, filters, k) {
  const kept = chunks.filter((c) => Object.entries(filters).every(([key, v]) => c.meta[key] === v));
  const scored = kept.map((c) => ({ id: c.id, s: c.text.includes(query) ? 2 : 1 }));
  scored.sort((a, b) => b.s - a.s);
  return scored.slice(0, k).map((r) => r.id);
}
const chunks = [
  { id: 'a', text: 'Runner v9 price 129', meta: { cat: 'shoes', v: 3 } },
  { id: 'b', text: 'Runner v9 price 129', meta: { cat: 'shoes', v: 2 } },
  { id: 'c', text: 'Sandal summer sale', meta: { cat: 'shoes', v: 3 } },
];
console.log(retrieve(chunks, 'Runner', { cat: 'shoes' }, 5).join(','));
console.log(retrieve(chunks, 'Runner', { cat: 'shoes', v: 3 }, 5).join(','));
console.log(retrieve(chunks, 'Runner', { cat: 'hats' }, 5).join(',') || 'empty-correct');

